// Unit tests for the messages ConfigMaps generated by setupConfigMaps against a
// fake API server. The reconciling Frontend lives in "boot", so the source base
// ConfigMap is boot/stage; target namespaces hold feo-context-cfg, and each base
// has one messages ConfigMap per published locale beside it.

const localeTestBase = "feo-context-cfg"

var english = crd.EnabledLocale{ID: "en", Name: "English", Default: true}

func localeConfigMapTestEnv(targets []string, enabled ...crd.EnabledLocale) *crd.FrontendEnvironment {
	return &crd.FrontendEnvironment{
		TypeMeta:   metav1.TypeMeta{APIVersion: crd.GroupVersion.String(), Kind: "FrontendEnvironment"},
		ObjectMeta: metav1.ObjectMeta{Name: "stage", UID: "stage-uid"},
		Spec: crd.FrontendEnvironmentSpec{
			SSO:              "https://sso.example.com/auth",
			TargetNamespaces: targets,
			EnabledLocales:   enabled,
		},
	}
}

func localeMessagesTestFrontend(locales crd.LocaleCatalogs) *crd.Frontend {
	return &crd.Frontend{
		ObjectMeta: metav1.ObjectMeta{Name: "app", Namespace: "boot"},
		Spec: crd.FrontendSpec{
			EnvName:          "stage",
			FeoConfigEnabled: true,
			Module:           &crd.FedModule{ModuleID: "app"},
			Locales:          locales,
		},
	}
}

// reconcileLocales runs setupConfigMaps for frontend and applies the resource
// cache, as a reconcile does. It returns the ConfigMaps that feed the config
// hash.
func reconcileLocales(t *testing.T, c client.Client, env *crd.FrontendEnvironment, frontend *crd.Frontend) []*v1.ConfigMap {
	t.Helper()
	ctx := context.Background()
	log := logr.Discard()
	cache := resCache.NewObjectCache(ctx, c, &log, resCache.NewCacheConfig(scheme, nil, nil, resCache.Options{}))
	cache.AddPossibleGVKFromIdent(CoreConfig)
	r := &FrontendReconciliation{
		Ctx: ctx, Client: c, Log: log, Cache: cache,
		FRE:                 &FrontendReconciler{Client: c},
		FrontendEnvironment: env,
		Frontend:            frontend,
	}
	hashed, err := r.setupConfigMaps()
	if err != nil {
		t.Fatal(err)
	}
	if err := cache.ApplyAll(); err != nil {
		t.Fatal(err)
	}
	return hashed
}

func newLocaleTestClient(objs ...client.Object) client.Client {
	return fake.NewClientBuilder().WithScheme(scheme).WithObjects(objs...).
		WithIndex(&crd.Frontend{}, "spec.envName", func(o client.Object) []string { return []string{o.(*crd.Frontend).Spec.EnvName} }).
		Build()
}

func getConfigMap(t *testing.T, c client.Client, ns, name string) (*v1.ConfigMap, error) {
	t.Helper()
	cm := &v1.ConfigMap{}
	return cm, c.Get(context.Background(), types.NamespacedName{Name: name, Namespace: ns}, cm)
}

// messagesConfigMap is a messages ConfigMap as the operator writes it for env.
func messagesConfigMap(env *crd.FrontendEnvironment, ns, baseName, locale string) *v1.ConfigMap {
	return &v1.ConfigMap{
		ObjectMeta: metav1.ObjectMeta{
			Name: messagesConfigMapName(baseName, locale), Namespace: ns,
			Labels:          map[string]string{"frontendenv": env.Name, messagesLocaleLabel: locale},
			OwnerReferences: []metav1.OwnerReference{env.MakeOwnerReference()},
		},
		Data: map[string]string{messagesFileName(locale): "{}"},
	}
}

// Every locale with strings gets messages, enabled or not; locales.json lists
// only the enabled ones, and an enabled locale without strings gets {}.
func TestLocaleMessagesPublishAll(t *testing.T) {
	env := localeConfigMapTestEnv([]string{"console", "console-2"}, english, crd.EnabledLocale{ID: "fr", Name: "Français"}, crd.EnabledLocale{ID: "zh-CN", Name: "简体中文"})
	env.Spec.Bundles = &[]crd.FrontendBundles{{ID: "iam", Title: "IAM"}}
	env.Spec.Locales = crd.LocaleCatalogs{"fr": {"bundles.iam.title": "IAM"}}
	fe := localeMessagesTestFrontend(crd.LocaleCatalogs{"ja": {moduleTitleKey: "アプリ"}})
	c := newLocaleTestClient(fe.DeepCopy())

	hashed := reconcileLocales(t, c, env, fe)

	want := map[string]string{
		"fr":    `{"bundle.iam.title":"IAM"}`,
		"ja":    `{"module.app.defaultDocumentTitle":"アプリ"}`,
		"zh-CN": `{}`,
	}
	for _, base := range []types.NamespacedName{{Namespace: "boot", Name: "stage"}, {Namespace: "console", Name: localeTestBase}, {Namespace: "console-2", Name: localeTestBase}} {
		for locale, data := range want {
			cm, err := getConfigMap(t, c, base.Namespace, messagesConfigMapName(base.Name, locale))
			if err != nil {
				t.Fatalf("%s %s: %v", base, locale, err)
			}
			if got := cm.Data; len(got) != 1 || got[messagesFileName(locale)] != data {
				t.Errorf("%s %s: data %v, want %s", base, locale, got, data)
			}
			if cm.Labels[messagesLocaleLabel] != locale || cm.Labels["frontendenv"] != env.Name {
				t.Errorf("%s %s: labels %v", base, locale, cm.Labels)
			}
			if _, ok := cm.Annotations["qontract.recycle"]; ok {
				t.Errorf("%s %s: messages must not recycle consumers", base, locale)
			}
			if !ownedBy(cm, env) {
				t.Errorf("%s %s: not owned by the environment", base, locale)
			}
		}
	}

	base, err := getConfigMap(t, c, "console", localeTestBase)
	if err != nil {
		t.Fatal(err)
	}
	if got, want := base.Data["locales.json"], `[{"id":"en","name":"English","default":true},{"id":"fr","name":"Français","file":"messages.fr.json"},{"id":"zh-CN","name":"简体中文","file":"messages.zh-CN.json"}]`; got != want {
		t.Errorf("locales.json: got %s, want %s", got, want)
	}
	if _, leaked := env.Labels[messagesLocaleLabel]; leaked {
		t.Errorf("the locale label leaked into the environment's labels: %v", env.Labels)
	}

	// translations stay out of the config hash, so changing them restarts nothing
	for _, cm := range hashed {
		if cm.Labels[messagesLocaleLabel] != "" {
			t.Errorf("messages ConfigMap %s/%s feeds the config hash", cm.Namespace, cm.Name)
		}
	}
}

func TestLocaleMessagesNotLocalized(t *testing.T) {
	env := localeConfigMapTestEnv([]string{"console"})
	fe := localeMessagesTestFrontend(nil)
	c := newLocaleTestClient(fe.DeepCopy())

	reconcileLocales(t, c, env, fe)

	list := &v1.ConfigMapList{}
	if err := c.List(context.Background(), list, client.HasLabels{messagesLocaleLabel}); err != nil {
		t.Fatal(err)
	}
	if len(list.Items) != 0 {
		t.Errorf("messages ConfigMaps written without any locale: %d", len(list.Items))
	}
	base, err := getConfigMap(t, c, "console", localeTestBase)
	if err != nil {
		t.Fatal(err)
	}
	if _, ok := base.Data["locales.json"]; ok {
		t.Error("locales.json written without enabled locales")
	}
}

// Strings staged for a locale that is not enabled are published but not
// advertised.
func TestLocaleMessagesStagedNotAdvertised(t *testing.T) {
	env := localeConfigMapTestEnv([]string{"console"})
	fe := localeMessagesTestFrontend(crd.LocaleCatalogs{"fr": {moduleTitleKey: "Application"}})
	c := newLocaleTestClient(fe.DeepCopy())

	reconcileLocales(t, c, env, fe)

	if _, err := getConfigMap(t, c, "console", messagesConfigMapName(localeTestBase, "fr")); err != nil {
		t.Errorf("staged locale not published: %v", err)
	}
	base, err := getConfigMap(t, c, "console", localeTestBase)
	if err != nil {
		t.Fatal(err)
	}
	if _, ok := base.Data["locales.json"]; ok {
		t.Error("locales.json written without enabled locales")
	}
}

func TestLocaleMessagesOversizeLeftOut(t *testing.T) {
	env := localeConfigMapTestEnv([]string{"console"}, english, crd.EnabledLocale{ID: "fr", Name: "Français"})
	env.Spec.Locales = crd.LocaleCatalogs{"fr": {}}
	env.Spec.Bundles = &[]crd.FrontendBundles{}
	// the CRD caps a catalog at 2048 keys of 4096 characters; 300 of 4096 is
	// already over the 900 KB messages limit
	for i := 0; i < 300; i++ {
		*env.Spec.Bundles = append(*env.Spec.Bundles, crd.FrontendBundles{ID: fmt.Sprintf("b%d", i)})
		env.Spec.Locales["fr"][fmt.Sprintf("bundles.b%d.title", i)] = crd.LocaleMessage(strings.Repeat("é", 4096))
	}
	fe := localeMessagesTestFrontend(nil)
	c := newLocaleTestClient(fe.DeepCopy())

	reconcileLocales(t, c, env, fe)

	if _, err := getConfigMap(t, c, "console", messagesConfigMapName(localeTestBase, "fr")); !k8serr.IsNotFound(err) {
		t.Errorf("oversize messages were written: %v", err)
	}
	base, err := getConfigMap(t, c, "console", localeTestBase)
	if err != nil {
		t.Fatal(err)
	}
	if got, want := base.Data["locales.json"], `[{"id":"en","name":"English","default":true}]`; got != want {
		t.Errorf("locales.json: got %s, want %s", got, want)
	}
}

// Only this environment's messages ConfigMaps beside a current base are pruned,
// and only for locales without messages.
func TestLocaleMessagesPrune(t *testing.T) {
	env := localeConfigMapTestEnv([]string{"console"}, english, crd.EnabledLocale{ID: "fr", Name: "Français"})
	other := localeConfigMapTestEnv(nil)
	other.Name, other.UID = "prod", "prod-uid"

	unowned := messagesConfigMap(env, "console", localeTestBase, "ko")
	unowned.OwnerReferences = nil
	foreignBase := messagesConfigMap(env, "console", "other-base", "de")
	existing := []client.Object{
		messagesConfigMap(env, "boot", "stage", "de"),                  // stale, beside the source base
		messagesConfigMap(env, "console", localeTestBase, "de"),        // stale, beside a target base
		messagesConfigMap(env, "console", localeTestBase, "fr"),        // still published
		messagesConfigMap(env, "removed-target", localeTestBase, "de"), // not a current target
		messagesConfigMap(other, "console", localeTestBase, "it"),      // another environment
		unowned,
		foreignBase,
	}
	fe := localeMessagesTestFrontend(nil)
	c := newLocaleTestClient(append(existing, fe.DeepCopy())...)

	reconcileLocales(t, c, env, fe)

	for _, gone := range []types.NamespacedName{{Namespace: "boot", Name: "stage-messages-de"}, {Namespace: "console", Name: "feo-context-cfg-messages-de"}} {
		if _, err := getConfigMap(t, c, gone.Namespace, gone.Name); !k8serr.IsNotFound(err) {
			t.Errorf("%s not pruned: %v", gone, err)
		}
	}
	kept := []types.NamespacedName{
		{Namespace: "console", Name: "feo-context-cfg-messages-fr"},
		{Namespace: "removed-target", Name: "feo-context-cfg-messages-de"},
		{Namespace: "console", Name: "feo-context-cfg-messages-it"},
		{Namespace: "console", Name: "feo-context-cfg-messages-ko"},
		{Namespace: "console", Name: "other-base-messages-de"},
	}
	for _, nn := range kept {
		if _, err := getConfigMap(t, c, nn.Namespace, nn.Name); err != nil {
			t.Errorf("%s pruned: %v", nn, err)
		}
	}
}

func TestPublishedLocaleIDs(t *testing.T) {
	env := localeConfigMapTestEnv(nil, english, crd.EnabledLocale{ID: "ko", Name: "한국어"})
	env.Spec.Locales = crd.LocaleCatalogs{"fr": {}}
	deleting := *localeMessagesTestFrontend(crd.LocaleCatalogs{"it": {}})
	now := metav1.Now()
	deleting.DeletionTimestamp = &now
	otherEnv := *localeMessagesTestFrontend(crd.LocaleCatalogs{"de": {}})
	otherEnv.Spec.EnvName = "prod"
	feList := &crd.FrontendList{Items: []crd.Frontend{*localeMessagesTestFrontend(crd.LocaleCatalogs{"ja": {}}), deleting, otherEnv}}

	if got, want := publishedLocaleIDs(feList, env), []string{"fr", "ja", "ko"}; !slices.Equal(got, want) {
		t.Errorf("got %v, want %v", got, want)
	}
}
